head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        MaxTab_01.setSelectedTabIndex(1);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20800.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_ISU_NM_onclick
 * @description img_ISU_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISU_NM_onclick = function() {
    try {
        $c.stockSearch.JongmokSearch(txb_ISU_CD, txb_ISU_NM, SECUGRP_ID_ST, js_market, "A");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20800.img_ISU_NM_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20800.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        if ($c.frame.path("NoData") !== null) {
            await $c.win.closePopup();
        }
        let Rows;
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            Rows = dts_List_1.getRowCount();
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            Rows = dts_List_2.getRowCount();
        }
        $c.stf.fillGridHeaderTotalCnt(Rows, panel_page);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20800.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20800.dts_List_1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_2_OnLoadCompleted
 * @description dts_List_2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20800.dts_List_2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadError
 * @description dts_List_1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20800.dts_List_1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_2_OnLoadError
 * @description dts_List_2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List_2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20800.dts_List_2_OnLoadError" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onblur
 * @description txb_ISU_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onblur = function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            txb_ISU_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20800.txb_ISU_CD_onblur" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀 다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF20800.xml", SCREN_PROCS_TP_CD_07); // 엑셀
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            $c.data.downloadGridViewExcel(grd_List_1, {fileName: "신형우선주 종목현황", type: "8"});
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            $c.data.downloadGridViewExcel(grd_List_2, {fileName: "신형우선주 주식발행현황", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20800.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20800.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        url += "?SCREN_ID=" + "ULDSTF20800.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral&outputMessageId=LISTED_SEARCH_NEWPREFSTK_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.newprefstk.condition" + "&{P}param01=" + rdo_LIST_STAT_CD.getValue() + // 상장구분
            "&{P}param02=" + rdo_LIST_STAT_CD.getValue() + // 상장구분
            "&{P}param03=" + txb_ISU_CD.getValue() + "&{P}param04=" + txb_ISU_CD.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        url += "?SCREN_ID=" + "ULDSTF20800.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral&outputMessageId=LISTED_SEARCH_NEWPREFSTK_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.newprefstkdtl.condition" + "&{P}param01=" + rdo_LIST_STAT_CD.getValue() + // 상장구분
            "&{P}param02=" + rdo_LIST_STAT_CD.getValue() + // 상장구분
            "&{P}param03=" + txb_ISU_CD.getValue() + "&{P}param04=" + txb_ISU_CD.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};
